'use strict';
(()=>{
 const $=id=>document.getElementById(id),G=JustinGame,request=(path,body)=>window.justinOnline.profileRequest(path,body),palette={purple:'#7851a9',green:'#527e22',blue:'#287fa0',pink:'#b94f87',orange:'#aa6923'};
 const editor=document.createElement('form');editor.id='account-editor';editor.innerHTML='<h3>Edit account</h3><label>Username<input id="profile-username" required minlength="3" maxlength="20" pattern="[A-Za-z0-9_]{3,20}" autocomplete="off"></label><div class="profile-options"><label>Chat avatar<select id="profile-avatar"></select></label><label>Name colour<select id="profile-colour"><option value="purple">Purple</option><option value="green">Green</option><option value="blue">Blue</option><option value="pink">Pink</option><option value="orange">Orange</option></select></label></div><button id="profile-save">Save account</button><small id="profile-status" role="status"></small>';$('account-profile').append(editor);
 const toggle=document.createElement('button');toggle.id='chat-toggle';toggle.type='button';toggle.setAttribute('aria-expanded','false');toggle.setAttribute('aria-controls','game-chat');toggle.innerHTML='<svg viewBox="0 0 30 26" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M3 2h23l1 17H12l-7 5 1-5H2Z"/><path d="M8 7h13M8 12h9"/></svg> Chat <i id="chat-unread" hidden></i>';document.body.append(toggle);
 const drawer=document.createElement('aside');drawer.id='game-chat';drawer.hidden=true;drawer.setAttribute('aria-label','Player chat');drawer.innerHTML='<div class="chat-heading"><b>Player chat</b><button type="button" id="chat-close" aria-label="Close chat">×</button></div><p id="chat-identity"></p><ol id="chat-messages" aria-live="polite" aria-relevant="additions"></ol><div id="chat-guest"><p>Sign in to chat.</p><button id="chat-sign-in">Sign in</button></div><form id="chat-form" hidden><input id="chat-text" aria-label="Chat message" placeholder="Message…" maxlength="180" autocomplete="off" required><button id="chat-send" aria-label="Send chat message">↗</button></form><small id="chat-status" role="status"></small>';document.body.append(drawer);
 let haveSnapshot=false,me=null,generation=0,revision=0,lastId=0,unread=0,loading=false,editorFor='',sending=null,editing=null;const nodes=new Map();
 const open=()=>{drawer.hidden=false;toggle.setAttribute('aria-expanded','true');unread=0;$('chat-unread').hidden=true;loadChat();if(me)$('chat-text').focus()};
 toggle.onclick=()=>{if(drawer.hidden)open();else close()};function close(){drawer.hidden=true;toggle.setAttribute('aria-expanded','false')}$('chat-close').onclick=close;$('chat-sign-in').onclick=()=>{$('account-open').click()};
 function portrait(img,id){const skin=G.skins.find(s=>s.id===id)||G.skins[0],url=window.JustinSprites?.url(skin);if(url&&img.src!==url)img.src=url}
 function render(data){if(!me||!data||data.revision<revision)return;revision=data.revision;const list=$('chat-messages'),bottom=list.scrollHeight-list.scrollTop-list.clientHeight<60,scroll=list.scrollTop,keep=new Set();let added=0;
  for(const m of data.messages){keep.add(m.id);let row=nodes.get(m.id);if(!row){row=document.createElement('li');row.className='chat-message';const img=document.createElement('img'),content=document.createElement('div'),heading=document.createElement('div'),name=document.createElement('b'),role=document.createElement('small'),text=document.createElement('p'),time=document.createElement('time'),remove=document.createElement('button');img.alt='';heading.className='chat-message-heading';text.textContent=m.text;time.textContent=new Date(m.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});remove.type='button';remove.textContent='×';remove.setAttribute('aria-label','Remove message from '+m.username);remove.onclick=async()=>{try{await request('/api/chat/remove',{id:m.id,requestId:crypto.randomUUID()});loadChat()}catch(e){$('chat-status').textContent=e.message}};heading.append(name,role,time,remove);content.append(heading,text);row.append(img,content);row.parts={img,name,role,remove};nodes.set(m.id,row);if(m.id>lastId&&haveSnapshot&&m.userId!==me.id)added++}const p=row.parts;p.img.dataset.avatar=m.avatar;portrait(p.img,m.avatar);p.name.textContent=m.username;p.name.style.color=palette[m.colour]||palette.purple;p.role.textContent=m.role;p.role.hidden=!m.role;p.remove.hidden=m.userId!==me.id&&!me.isAdmin;p.remove.disabled=m.role==='Owner'&&!me.isOwner&&m.userId!==me.id;row.classList.toggle('is-me',m.userId===me.id)}
  for(const [id]of nodes)if(!keep.has(id))nodes.delete(id);list.replaceChildren(...data.messages.map(m=>nodes.get(m.id)));if(bottom)list.scrollTop=list.scrollHeight;else list.scrollTop=scroll;haveSnapshot=true;lastId=Math.max(lastId,...data.messages.map(m=>m.id),0);if(drawer.hidden&&added){unread+=added;$('chat-unread').textContent=unread>9?'9+':unread;$('chat-unread').hidden=false}else if(added)window.JustinGUIAudio?.play('ui');
 }
 async function loadChat(){if(loading||document.hidden)return;loading=true;const ticket=generation;try{const data=await request('/api/chat');if(ticket!==generation)return;me=data.profile;$('chat-guest').hidden=true;$('chat-form').hidden=false;$('chat-identity').textContent='Chatting as '+me.username;render(data);$('chat-status').textContent=''}catch(e){if(ticket!==generation)return;me=null;$('chat-guest').hidden=false;$('chat-form').hidden=true;$('chat-identity').textContent='';if(e.status!==401)$('chat-status').textContent=e.message}finally{loading=false}}
 async function loadEditor(){if(new URLSearchParams(location.search).has('ownerView')){editor.hidden=true;return}const ticket=generation;try{const p=await request('/api/profile');if(ticket!==generation)return;editor.hidden=false;editorFor=p.id;$('profile-username').value=p.username;$('profile-avatar').replaceChildren(...G.sortedSkins().filter(s=>p.owned.includes(s.id)).map(s=>{const o=document.createElement('option');o.value=s.id;o.textContent=s.name;return o}));$('profile-avatar').value=p.avatar;$('profile-colour').value=p.colour;$('profile-status').textContent=''}catch{editor.hidden=true}}
 $('account-open').addEventListener('click',loadEditor);
 editor.onsubmit=async e=>{e.preventDefault();const payload={username:$('profile-username').value,avatar:$('profile-avatar').value,colour:$('profile-colour').value};if(editing&&JSON.stringify(editing.payload)!==JSON.stringify(payload)){$('profile-status').textContent='Retry the previous save first.';return}editing??={payload,requestId:crypto.randomUUID()};$('profile-save').disabled=true;try{const data=await request('/api/profile',{...payload,requestId:editing.requestId});editing=null;window.justinOnline.applyProfile(data);$('profile-status').textContent='Account saved.';loadChat()}catch(error){if(error.status)editing=null;$('profile-status').textContent=error.message}finally{$('profile-save').disabled=false}};
 $('chat-form').onsubmit=async e=>{e.preventDefault();if(!me)return;const text=$('chat-text').value.trim();if(sending&&sending.text!==text){$('chat-status').textContent='Retry the previous message first.';return}sending??={text,requestId:crypto.randomUUID()};$('chat-send').disabled=true;try{await request('/api/chat',sending);sending=null;$('chat-text').value='';$('chat-status').textContent='';await loadChat()}catch(error){if(error.status)sending=null;$('chat-status').textContent=error.message}finally{$('chat-send').disabled=false}};
 let account='';window.addEventListener('justin-account-change',e=>{const id=e.detail.user?.id||'';if(id===account){if(me)loadChat();return}account=id;generation++;me=null;haveSnapshot=false;revision=lastId=unread=0;nodes.clear();$('chat-messages').replaceChildren();$('chat-unread').hidden=true;sending=editing=null;editorFor='';$('chat-form').hidden=true;$('chat-guest').hidden=false;loadChat()});
 window.addEventListener('justin-chat-snapshot',e=>{if(!me){if(account)loadChat();return}render(e.detail)});document.addEventListener('visibilitychange',()=>{if(!document.hidden)loadChat()});setInterval(()=>{if(!drawer.hidden&&!document.hidden)for(const img of drawer.querySelectorAll('[data-avatar]'))portrait(img,img.dataset.avatar)},1000);loadChat();
})();
